CREATE VIEW library_tracked_shelf_stock AS SELECT e.material_id,c.location_id,c.condition,COUNT(*) AS quantity FROM library_copies c JOIN library_editions e ON e.id=c.edition_id WHERE c.registration='registered' AND c.physical_state='on_shelf' GROUP BY e.material_id,c.location_id,c.condition;
