CREATE TRIGGER holdings_tracked_update_guard BEFORE UPDATE ON holdings WHEN EXISTS(SELECT 1 FROM library_tracked_shelf_stock t WHERE (t.material_id=OLD.material_id AND t.location_id=OLD.location_id AND t.condition=OLD.condition) OR (t.material_id=NEW.material_id AND t.location_id=NEW.location_id AND t.condition=NEW.condition)) BEGIN SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE ((NEW.material_id!=OLD.material_id OR NEW.location_id!=OLD.location_id OR NEW.condition!=OLD.condition) AND COALESCE((SELECT quantity FROM library_tracked_shelf_stock t WHERE t.material_id=OLD.material_id AND t.location_id=OLD.location_id AND t.condition=OLD.condition),0)>0) OR NEW.quantity < COALESCE((SELECT quantity FROM library_tracked_shelf_stock t WHERE t.material_id=NEW.material_id AND t.location_id=NEW.location_id AND t.condition=NEW.condition),0)+COALESCE((SELECT SUM(r.reserved_quantity-r.issued_quantity-r.released_quantity) FROM material_request_reservations r WHERE r.material_id=NEW.material_id AND r.source_location_id=NEW.location_id AND r.condition=NEW.condition),0); END;
--> statement-breakpoint
CREATE TRIGGER holdings_tracked_delete_guard BEFORE DELETE ON holdings BEGIN SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE COALESCE((SELECT quantity FROM library_tracked_shelf_stock t WHERE t.material_id=OLD.material_id AND t.location_id=OLD.location_id AND t.condition=OLD.condition),0)>0; END;
--> statement-breakpoint
CREATE TRIGGER reservation_tracked_insert_guard BEFORE INSERT ON material_request_reservations BEGIN SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE NEW.reserved_quantity-NEW.issued_quantity-NEW.released_quantity+COALESCE((SELECT SUM(r.reserved_quantity-r.issued_quantity-r.released_quantity) FROM material_request_reservations r WHERE r.material_id=NEW.material_id AND r.source_location_id=NEW.source_location_id AND r.condition=NEW.condition),0)+COALESCE((SELECT quantity FROM library_tracked_shelf_stock t WHERE t.material_id=NEW.material_id AND t.location_id=NEW.source_location_id AND t.condition=NEW.condition),0)>COALESCE((SELECT quantity FROM holdings h WHERE h.material_id=NEW.material_id AND h.location_id=NEW.source_location_id AND h.condition=NEW.condition),0); END;
