CREATE TRIGGER reservation_tracked_update_guard BEFORE UPDATE ON material_request_reservations BEGIN SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE NEW.reserved_quantity-NEW.issued_quantity-NEW.released_quantity+COALESCE((SELECT SUM(r.reserved_quantity-r.issued_quantity-r.released_quantity) FROM material_request_reservations r WHERE r.material_id=NEW.material_id AND r.source_location_id=NEW.source_location_id AND r.condition=NEW.condition AND r.id!=OLD.id),0)+COALESCE((SELECT quantity FROM library_tracked_shelf_stock t WHERE t.material_id=NEW.material_id AND t.location_id=NEW.source_location_id AND t.condition=NEW.condition),0)>COALESCE((SELECT quantity FROM holdings h WHERE h.material_id=NEW.material_id AND h.location_id=NEW.source_location_id AND h.condition=NEW.condition),0); END;
