CREATE TRIGGER copy_registered_update_guard BEFORE UPDATE ON library_copies BEGIN SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE OLD.registration='registered' AND (NEW.registration!='registered' OR NEW.edition_id!=OLD.edition_id);
SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE NEW.registration='registered' AND (NOT EXISTS(SELECT 1 FROM library_editions e JOIN materials m ON m.id=e.material_id WHERE e.id=NEW.edition_id AND m.status='active') OR NOT EXISTS(SELECT 1 FROM locations WHERE id=NEW.location_id AND status='active' AND type!='service'));
