CREATE TRIGGER material_tracked_archive_guard BEFORE UPDATE OF status,archived_at ON materials WHEN NEW.status!='active' OR NEW.archived_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE EXISTS(SELECT 1 FROM library_copies c JOIN library_editions e ON e.id=c.edition_id WHERE e.material_id=OLD.id AND c.registration='registered' AND c.physical_state!='withdrawn'); END;
