CREATE TRIGGER location_tracked_close_guard BEFORE UPDATE OF status ON locations WHEN NEW.status!='active' BEGIN SELECT RAISE(ABORT,'tracked_stock_conflict') WHERE EXISTS(SELECT 1 FROM library_copies WHERE location_id=OLD.id AND registration='registered' AND physical_state!='withdrawn'); END;
